import{_ as t,o as i,c as n,ah as o}from"./chunks/framework.BsNNkeaH.js";const m=JSON.parse('{"title":"Infirmary","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/infirmerie/index.md","filePath":"src/en/guide/infirmerie/index.md"}'),a={name:"en/guide/infirmerie/index.md"};function r(s,e,h,d,g,l){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="infirmary" tabindex="-1">Infirmary <a class="header-anchor" href="#infirmary" aria-label="Permalink to &quot;Infirmary&quot;">​</a></h1><p>As the person in charge of the infirmary, you record in ERA every student visit to the infirmary: the reason, the care given, and the outcome (returned to class or sent home). The <strong>Student services</strong> space gives you access to one page, <strong>Infirmary visits</strong>, which lists every visit and lets you create, view, or edit them.</p><h2 id="viewing-visits" tabindex="-1">Viewing visits <a class="header-anchor" href="#viewing-visits" aria-label="Permalink to &quot;Viewing visits&quot;">​</a></h2><p>The <strong>Infirmary visits</strong> page lists recorded visits, with the date and time, the student concerned, the reason, and the outcome (shown as a badge: <strong>Returned to class</strong> or <strong>Sent home</strong>, the latter highlighted in red). You can search for a visit by student name using the search field at the top of the page. Click a row to open a summary panel showing the date and time, the reason, and the outcome.</p><h2 id="recording-a-new-visit" tabindex="-1">Recording a new visit <a class="header-anchor" href="#recording-a-new-visit" aria-label="Permalink to &quot;Recording a new visit&quot;">​</a></h2><ol><li>Click <strong>New visit</strong> at the top of the <strong>Infirmary visits</strong> page.</li><li>Select the <strong>Student</strong> concerned.</li><li>Fill in the <strong>Date and time</strong> of the visit.</li><li>Describe the <strong>Reason</strong> for the visit (what brought the student to the infirmary).</li><li>The <strong>Care given</strong> field is optional: describe the care provided, if any.</li><li>Choose the <strong>Outcome</strong>: <strong>Returned to class</strong> if the student goes back to class, or <strong>Sent home</strong> if they need to go home.</li><li>Click <strong>Save</strong>.</li></ol><p>If you choose the <strong>Sent home</strong> outcome, the student&#39;s guardians automatically receive a notification with the reason and time of the visit — you don&#39;t need to do anything else on your end.</p><h2 id="viewing-and-editing-an-existing-visit" tabindex="-1">Viewing and editing an existing visit <a class="header-anchor" href="#viewing-and-editing-an-existing-visit" aria-label="Permalink to &quot;Viewing and editing an existing visit&quot;">​</a></h2><ol><li>From the <strong>Infirmary visits</strong> page, click <strong>Edit</strong> on the row for the visit in question (or first open the summary panel by clicking the row, then click <strong>Edit</strong> from that panel).</li><li>Update the student, date and time, reason, care given, or outcome as needed.</li><li>Click <strong>Save changes</strong>.</li></ol><p>If you change the outcome to <strong>Sent home</strong> when it wasn&#39;t already, the student&#39;s guardians are notified at the moment you save the change, just as for a new visit.</p><h3 id="deleting-a-visit" tabindex="-1">Deleting a visit <a class="header-anchor" href="#deleting-a-visit" aria-label="Permalink to &quot;Deleting a visit&quot;">​</a></h3><p>From the <strong>Infirmary visits</strong> page, click <strong>Delete</strong> on the row for the visit in question, then confirm in the dialog that appears. This permanently deletes the record and cannot be undone.</p>',12)])])}const u=t(a,[["render",r]]);export{m as __pageData,u as default};
